// Point / rectangle / quad list geometry shaders as SPIR-V, generated by Xenia's own code: the body of
// VulkanPipelineCache::GetGeometryShader (xenia/gpu/vulkan/vulkan_pipeline_cache.cc) from after its
// cache lookup up to `builder.dump(shader_code);` is extracted at configure time into
// xe_geometry_shader_body.inc (switch/CMakeLists.txt; switch/tools/spirv_glsl_test.sh for the PC
// check), so the generator is used unmodified and without the Vulkan pipeline cache around it.
#include <cstdint>
#include <vector>

#include "xenia/base/assert.h"
#include "xenia/base/logging.h"
#include "xenia/base/math.h"
#include "xenia/gpu/spirv_builder.h"
#include "xenia/gpu/spirv_compatibility.h"
#include "xenia/gpu/spirv_shader_translator.h"
#include "xenia/gpu/xenos.h"
#include "third_party/glslang/SPIRV/GLSL.std.450.h"

namespace xe {
namespace gpu {
namespace {
// Same definitions as in xenia/gpu/vulkan/vulkan_pipeline_cache.h (which needs Vulkan headers).
enum class PipelineGeometryShader : uint32_t { kNone, kPointList, kRectangleList, kQuadList };
union GeometryShaderKey {
  uint32_t key;
  struct {
    PipelineGeometryShader type : 2;
    uint32_t interpolator_count : 5;
    uint32_t has_user_clip_planes : 1;
    uint32_t user_clip_plane_cull : 1;
    uint32_t has_vertex_kill_and : 1;
    uint32_t has_point_size : 1;
    uint32_t has_point_coordinates : 1;
  };
  GeometryShaderKey() : key(0) {}
};

std::vector<unsigned int> build(GeometryShaderKey key) {
#include "xe_geometry_shader_body.inc"
  return shader_code;
}
}  // namespace
}  // namespace gpu
}  // namespace xe

// key: GeometryShaderKey bits (type in bits 0-1, as gl_bridge.cc packs them).
std::vector<unsigned int> lsw_build_geometry_shader_spirv(uint32_t key_bits) {
  xe::gpu::GeometryShaderKey key;
  key.key = key_bits;
  if (key.type == xe::gpu::PipelineGeometryShader::kNone) return {};
  return xe::gpu::build(key);
}
